using System;using System.Collections.Concurrent;using System.Net;using System.Net.Sockets;using System.Net.WebSockets;using System.Text;using System.Text.RegularExpressions;using System.Threading;using System.Threading.Tasks;using UnityEngine;
public class CloudOscBridge:MonoBehaviour{public string relayUrl="wss://YOUR-WORKER.workers.dev";public string roomCode="CHANGE-ME";public bool allowLanTargets=false;public string forcedHost="127.0.0.1";public int forcedPort=3336;ClientWebSocket ws;CancellationTokenSource cts;UdpClient udp;readonly ConcurrentQueue<M>q=new();static readonly Regex Addr=new Regex(@"^/[a-z0-9]+(?:/[a-z0-9-]+)*$");[Serializable]class M{public string type,address,valueType,oscHost;public int oscPort,channel;public float value;}
async void Start(){udp=new UdpClient();cts=new CancellationTokenSource();await Loop(cts.Token);}async Task Loop(CancellationToken t){while(!t.IsCancellationRequested){try{ws?.Dispose();ws=new ClientWebSocket();var u=relayUrl.TrimEnd('/').Replace("https://","wss://").Replace("http://","ws://");await ws.ConnectAsync(new Uri($"{u}/room/{roomCode}?role=unity"),t);var b=new byte[4096];while(ws.State==WebSocketState.Open&&!t.IsCancellationRequested){var r=await ws.ReceiveAsync(new ArraySegment<byte>(b),t);if(r.MessageType==WebSocketMessageType.Close)break;var m=JsonUtility.FromJson<M>(Encoding.UTF8.GetString(b,0,r.Count));if(m!=null&&m.type=="osc")q.Enqueue(m);}}catch(Exception e){Debug.LogWarning(e.Message);}if(!t.IsCancellationRequested)await Task.Delay(5000,t);}}
void Update(){while(q.TryDequeue(out var m)){if(!Addr.IsMatch(m.address)){Debug.LogWarning($"[OSC Warning] Invalid address: {m.address}");continue;}var host=allowLanTargets?m.oscHost:forcedHost;var port=allowLanTargets?m.oscPort:forcedPort;if(port<1||port>65535){Debug.LogWarning("[OSC Warning] Invalid port");continue;}var p=Packet(m.address,m.value,m.valueType);udp.Send(p,p.Length,host,port);}}
static byte[] S(string s){var b=Encoding.UTF8.GetBytes(s+"\0");Array.Resize(ref b,(b.Length+3)&~3);return b;}static byte[] Packet(string a,float v,string type){var ab=S(a);var tb=S(type=="int"?",i":",f");byte[]d;if(type=="int"){var n=IPAddress.HostToNetworkOrder(Mathf.RoundToInt(v));d=BitConverter.GetBytes(n);}else{d=BitConverter.GetBytes(v);if(BitConverter.IsLittleEndian)Array.Reverse(d);}var p=new byte[ab.Length+tb.Length+4];Buffer.BlockCopy(ab,0,p,0,ab.Length);Buffer.BlockCopy(tb,0,p,ab.Length,tb.Length);Buffer.BlockCopy(d,0,p,ab.Length+tb.Length,4);return p;}void OnDestroy(){cts?.Cancel();ws?.Dispose();udp?.Dispose();cts?.Dispose();}}
